import { readFileSync } from 'node:fs'
import { merge } from './merge.js'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) {
  fail('usage: cli.js merge|merge2|regions')
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const line of lines) {
  if (line === '%%%') docs.push([])
  else docs[docs.length - 1].push(line)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')

const regions = merge(docs[0], docs[1], docs[2])
const out = []
